.sl-slider-carousel {
    background-color: var(--smartlearn-bg);
    font-family: var(--smartlearn-body-font, inherit);
    padding-block: clamp(3rem, 6vw, 5rem);
    overflow-x: clip;
}
.sl-slider-carousel .sl-container {
    max-width: 1200px;
    margin-inline: auto;
    padding-inline: 1rem;
}
.sl-slider-carousel .sl-carousel-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 2.5rem;
    flex-wrap: wrap;
    gap: 1rem;
}
.sl-slider-carousel .sl-section-title {
    font-family: var(--smartlearn-heading-font, inherit);
    font-size: clamp(1.75rem, 3vw, 2.25rem);
    font-weight: 700;
    color: var(--smartlearn-text);
    margin-bottom: 0.5rem;
}
.sl-slider-carousel .sl-section-subtitle {
    font-size: 1.125rem;
    color: var(--smartlearn-text-muted);
    margin: 0;
}
.sl-slider-carousel .sl-carousel-arrows { display: flex; gap: 0.5rem; }
.sl-slider-carousel .sl-c-btn {
    background: var(--smartlearn-card-bg);
    border: 1px solid var(--smartlearn-card-border);
    color: var(--smartlearn-text);
    width: 44px;
    height: 44px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}
.sl-slider-carousel .sl-c-btn:hover:not(:disabled),
.sl-slider-carousel .sl-c-btn:focus-visible:not(:disabled) {
    background: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text) !important;
    border-color: var(--smartlearn-btn-bg);
}
.sl-slider-carousel .sl-c-btn:focus-visible,
.sl-slider-carousel .sl-c-link:focus-visible,
.sl-slider-carousel .sl-carousel-track:focus-visible {
    outline: 3px solid var(--smartlearn-primary);
    outline-offset: 3px;
}
.sl-slider-carousel .sl-c-btn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}
.sl-slider-carousel .sl-carousel-track-container { width: 100%; }
.sl-slider-carousel .sl-carousel-track {
    display: flex;
    gap: 1.5rem;
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    scrollbar-width: none;
    -ms-overflow-style: none;
    padding-inline: 1rem;
    padding-bottom: 1.5rem;
    touch-action: pan-y;
}
.sl-slider-carousel .sl-carousel-track::-webkit-scrollbar { display: none; }
.sl-slider-carousel .sl-c-card {
    flex: 0 0 85%;
    max-width: 380px;
    scroll-snap-align: start;
    background: var(--smartlearn-card-bg);
    border-radius: var(--smartlearn-radius, 1rem);
    overflow: hidden;
    border: 1px solid var(--smartlearn-card-border);
    box-shadow: 0 4px 6px rgba(0,0,0,0.03);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    display: flex;
    flex-direction: column;
}
@media (min-width: 768px) {
    .sl-slider-carousel .sl-carousel-track {
        padding-inline: max(1rem, calc((100% - 1200px) / 2));
    }
    .sl-slider-carousel .sl-c-card {
        flex: 0 0 380px;
    }
}
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
    .sl-slider-carousel .sl-c-card:hover {
        transform: translateY(-5px);
        box-shadow: 0 15px 30px rgba(0,0,0,0.08);
    }
}
.sl-slider-carousel .sl-c-img { position: relative; aspect-ratio: 4/3; width: 100%; }
.sl-slider-carousel .sl-c-img img { width: 100%; height: 100%; object-fit: cover; }
.sl-slider-carousel .sl-c-badge {
    position: absolute;
    top: 1rem;
    inset-inline-start: 1rem;
    background: var(--smartlearn-card-bg);
    color: var(--smartlearn-text);
    border: 1px solid var(--smartlearn-card-border);
    padding: 0.25rem 0.75rem;
    border-radius: 2rem;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    box-shadow: 0 2px 5px rgba(0,0,0,0.1);
}
.sl-slider-carousel .sl-c-body { padding: 1.5rem; display: flex; flex-direction: column; flex: 1; }
.sl-slider-carousel .sl-c-title {
    font-family: var(--smartlearn-heading-font, inherit);
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--smartlearn-text);
    margin-bottom: 0.75rem;
}
.sl-slider-carousel .sl-c-desc {
    font-size: 1rem;
    color: var(--smartlearn-text-muted);
    margin-bottom: 1.5rem;
    flex: 1;
}
.sl-slider-carousel .sl-c-link-row {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
}
.sl-slider-carousel .sl-c-link {
    color: var(--smartlearn-primary);
    font-weight: 600;
    text-decoration: none;
    transition: color 0.2s;
}
.sl-slider-carousel .sl-c-link:hover,
.sl-slider-carousel .sl-c-link:focus-visible {
    color: var(--smartlearn-primary-hover, var(--smartlearn-primary));
    text-decoration: underline;
}
.sl-slider-carousel .sl-c-link-arrow {
    color: var(--smartlearn-primary);
    font-weight: 600;
}
[dir="rtl"] .sl-slider-carousel .sl-c-btn svg,
[dir="rtl"] .sl-slider-carousel .sl-c-link-arrow {
    display: inline-block;
    transform: scaleX(-1);
}
@media (prefers-reduced-motion: reduce) {
    .sl-slider-carousel .sl-c-btn,
    .sl-slider-carousel .sl-c-card,
    .sl-slider-carousel .sl-c-link { transition: none; }
}

js:
(function() {
    function init() {
        var sections = document.querySelectorAll('.sl-slider-carousel');
        var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

        sections.forEach(function(root) {
            if (root.dataset.slInit === '1') return;
            root.dataset.slInit = '1';

            var track = root.querySelector('.sl-carousel-track');
            var prev = root.querySelector('.sl-c-prev');
            var next = root.querySelector('.sl-c-next');
            if (!track || !prev || !next) return;

            function getStep() {
                var card = track.querySelector('.sl-c-card');
                if (!card) return 380;
                var style = window.getComputedStyle(track);
                var gap = parseFloat(style.columnGap || style.gap) || 24;
                return card.getBoundingClientRect().width + gap;
            }

            function isRtl() {
                return window.getComputedStyle(root).direction === 'rtl';
            }

            function scrollDir(direction) {
                var sign = isRtl() ? -direction : direction;
                track.scrollBy({ left: sign * getStep(), behavior: prefersReduced ? 'auto' : 'smooth' });
            }

            function updateButtons() {
                var maxScroll = track.scrollWidth - track.clientWidth;
                if (maxScroll <= 2) {
                    prev.disabled = true;
                    next.disabled = true;
                    return;
                }
                var pos = Math.abs(track.scrollLeft);
                prev.disabled = pos <= 2;
                next.disabled = pos >= maxScroll - 2;
            }

            prev.addEventListener('click', function() { scrollDir(-1); });
            next.addEventListener('click', function() { scrollDir(1); });

            track.addEventListener('keydown', function(e) {
                if (e.key === 'ArrowLeft') {
                    e.preventDefault();
                    scrollDir(isRtl() ? 1 : -1);
                } else if (e.key === 'ArrowRight') {
                    e.preventDefault();
                    scrollDir(isRtl() ? -1 : 1);
                }
            });

            var scrollTimer = null;
            track.addEventListener('scroll', function() {
                clearTimeout(scrollTimer);
                scrollTimer = setTimeout(updateButtons, 60);
            }, { passive: true });
            window.addEventListener('resize', updateButtons, { passive: true });
            updateButtons();
        });
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
